import unittest
from services.image_processor import ImageProcessor
from repositories.opensearch_repo import OpenSearchRepo
from repositories.storage_s3_repo import StorageS3Repo
from repositories.face_image_score_repo import FaceImageScoreRepo
from repositories.web_image_repo import WebImageRepo
from data.image_type_enum import ImageTypeEnum
from data.scan_dto import ScanDTO, UserImageFace
from data.user_image_entity import UserImageEntity
from data.scan_request_dto import ScanRequestDTO
from config import Config
from pymongo import MongoClient

class TestImageProcessor(unittest.TestCase):
    def setUp(self):
        self._configs = Config.get()
        self._vector_repo = OpenSearchRepo()
        self._storage = StorageS3Repo()
        self._db_client = MongoClient(self._configs.DB_URL)
        self._face_image_score_repo = FaceImageScoreRepo(self._db_client, self._configs.DB_NAME, self._configs.FACE_IMAGE_SCORE_REPO_NAME)
        self._web_image_repo = WebImageRepo(self._db_client, self._configs.DB_NAME, self._configs.WEB_IMAGE_REPO_NAME)
        self._image_processor = ImageProcessor(self._vector_repo, self._storage, self._face_image_score_repo, self._web_image_repo)

    def test_embed_image(self):
        """
        This is an integration test, it tests embedding an image using the real face recognition model
        """
        # mock image path
        img_path = 'tests/data/mary_peltola.jpg'

        # mock image storage id
        img_storage_id = 'test-data-storage-id.jpg'

        # embed image
        res = self._storage.add_image(ImageTypeEnum.USER, img_storage_id, img_path)
        face_dicts = self._image_processor.embed_image(self._storage.get_storage_by_type(ImageTypeEnum.USER), img_storage_id)

        self.assertEqual(len(face_dicts), 1)
        self.assertEqual(len(face_dicts[0]['embedding']), 512)
        self.assertEqual(face_dicts[0]['embedding'][0], -0.34365490078926086)
        self.assertEqual(face_dicts[0]['embedding'][511], -0.996613621711731)

